using System; using System.Collections.Generic; using System.Net.Http; using System.Net.WebSockets; using System.Text; using System.Threading; using System.Threading.Tasks; using Newtonsoft.Json; using Newtonsoft.Json.Linq;
namespace Zekumo {
 public sealed class ZekumoException:Exception { public int Status{get;} public string Code{get;} public ZekumoException(int s,string c,string m):base(m){Status=s;Code=c;} }
 public sealed class ZekumoClient:IDisposable {
  public string AppId{get;} public string BaseUrl{get;} public string Token{get;set;} readonly HttpClient http;
  public ZekumoClient(string appId,string baseUrl,string token="",HttpClient client=null){AppId=appId;BaseUrl=baseUrl.TrimEnd('/');Token=token;http=client??new HttpClient{Timeout=TimeSpan.FromSeconds(30)};}
  static string S(object x)=>Uri.EscapeDataString(Convert.ToString(x)); static string Q(Dictionary<string,object> q){var p=new List<string>();foreach(var x in q)if(x.Value!=null&&Convert.ToString(x.Value)!=""&&Convert.ToString(x.Value)!="0")p.Add(S(x.Key)+"="+S(x.Value));return p.Count==0?"":"?"+string.Join("&",p);}
  public async Task<JToken> Request(string method,string path,object body=null,bool auth=true,CancellationToken ct=default){var r=new HttpRequestMessage(new HttpMethod(method),BaseUrl+path);if(body!=null)r.Content=new StringContent(JsonConvert.SerializeObject(body),Encoding.UTF8,"application/json");if(auth&&!string.IsNullOrEmpty(Token))r.Headers.Authorization=new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer",Token);var z=await http.SendAsync(r,ct);var raw=await z.Content.ReadAsStringAsync();JToken data=null;try{if(raw.Length>0)data=JToken.Parse(raw);}catch{}if(!z.IsSuccessStatusCode){var e=data?["error"];throw new ZekumoException((int)z.StatusCode,(string)e?["code"]??"http_"+(int)z.StatusCode,(string)e?["message"]??raw);}return data;}
  async Task<JToken> Login(string path,Dictionary<string,object>b){b["app_id"]=AppId;var x=await Request("POST",path,b,false);Token=(string)x["token"];return x;}
  static Dictionary<string,object>M(params object[]x){var m=new Dictionary<string,object>();for(int i=0;i<x.Length;i+=2)if(x[i+1]!=null)m[(string)x[i]]=x[i+1];return m;}
  public Task<JToken> LoginGuest(string id,string nick="")=>Login("/v1/auth/login",M("provider","guest","device_id",id,"nickname",nick)); public Task<JToken> LoginPassword(string u,string p)=>Login("/v1/auth/login",M("provider","password","username",u,"password",p)); public Task<JToken> LoginTicket(string t)=>Login("/v1/auth/login",M("provider","sso","ticket",t)); public Task<JToken> Register(string u,string p,string n="")=>Login("/v1/auth/register",M("provider","password","username",u,"password",p,"nickname",n)); public void Logout()=>Token="";
  public Task<JToken> Player()=>Request("GET","/v1/player/profile"); public Task<JToken> UpdatePlayer(string n=null,object p=null)=>Request("PUT","/v1/player/profile",M("nickname",n,"profile",p)); public Task<JToken> Bind(string t="",string u="",string p="")=>Request("POST","/v1/player/bind",M("ticket",t,"username",u,"password",p));
  public Task<JToken> DataList()=>Request("GET","/v1/player/data"); public Task<JToken> DataGet(string k)=>Request("GET","/v1/player/data/"+S(k)); public Task<JToken> DataSet(string k,object v)=>Request("PUT","/v1/player/data/"+S(k),M("value",v)); public Task<JToken> DataDelete(string k)=>Request("DELETE","/v1/player/data/"+S(k));
  public Task<JToken> Submit(string b,long s,string mode="max")=>Request("POST","/v1/leaderboards/"+S(b)+"/score",M("score",s,"mode",mode)); public Task<JToken> Top(string b,int limit=0,int offset=0,string scope="")=>Request("GET","/v1/leaderboards/"+S(b)+Q(M("limit",limit,"offset",offset,"scope",scope))); public Task<JToken> Rank(string b)=>Request("GET","/v1/leaderboards/"+S(b)+"/me");
  public Task<JToken> Achievements(bool unlocked=false)=>Request("GET","/v1/achievements"+(unlocked?"/unlocked":"")); public Task<JToken> Friends()=>Request("GET","/v1/friends"); public Task<JToken> FriendRequests()=>Request("GET","/v1/friends/requests"); public Task<JToken> FriendAction(string a,string id)=>Request("POST","/v1/friends/"+a,M(a=="request"||a=="block"?"target_player_id":"request_id",id)); public Task<JToken> RemoveFriend(string id)=>Request("DELETE","/v1/friends/"+S(id));
  public Task<JToken> Balances()=>Request("GET","/v1/currency"); public Task<JToken> Ledger(string id,int limit=0,int offset=0)=>Request("GET","/v1/currency/"+S(id)+"/ledger"+Q(M("limit",limit,"offset",offset))); public Task<JToken> Spend(string id,long amount,string key,string note="")=>Request("POST","/v1/currency/"+S(id)+"/spend",M("amount",amount,"idempotency_key",key,"note",note));
  public Task<JToken> Mailbox(bool unread=false)=>Request("GET","/v1/mailbox"+(unread?"?unread_only=true":"")); public Task<JToken> MailAction(string id,string action)=>Request("POST","/v1/mailbox/"+S(id)+"/"+action); public Task<JToken> Announcements(Dictionary<string,object>q)=>Request("GET","/v1/apps/"+S(AppId)+"/announcements"+Q(q),null,false); public Task<JToken> Call(string n,object b=null,bool pub=false)=>Request("POST",pub?"/v1/apps/"+S(AppId)+"/functions/"+S(n):"/v1/functions/"+S(n),b,!pub); public Task<JToken> Updates(string v,Dictionary<string,object>q){q["version"]=v;return Request("GET","/v1/apps/"+S(AppId)+"/updates/check"+Q(q),null,false);} public Task<JToken> Releases()=>Request("GET","/v1/apps/"+S(AppId)+"/releases",null,false);
  public Task<JToken> ReportLog(object x)=>Request("POST","/v1/logs",x); public Task<JToken> Dialogues()=>Request("GET","/v1/dialogues"); public Task<JToken> Dialogue(string k)=>Request("GET","/v1/dialogues/"+S(k)); public Task<JToken> ChatHistory(string c,long before=0,int limit=0)=>Request("GET","/v1/chat/history"+Q(M("channel",c,"before_id",before,"limit",limit))); public Task<JToken> KvGet(string n,string k)=>Request("GET","/v1/kv/"+S(n)+"/"+S(k)); public Task<JToken> KvList(string n,int l=0,int o=0)=>Request("GET","/v1/kv/"+S(n)+Q(M("limit",l,"offset",o)));
  public ZekumoRealtime Realtime()=>new ZekumoRealtime(this); public void Dispose()=>http.Dispose();
 }
 public sealed class ZekumoRealtime:IDisposable { readonly ZekumoClient c;ClientWebSocket ws;CancellationTokenSource stop;public event Action<string,JToken> Event;public ZekumoRealtime(ZekumoClient x){c=x;}public async Task Connect(CancellationToken ct=default){ws=new ClientWebSocket();stop=CancellationTokenSource.CreateLinkedTokenSource(ct);await ws.ConnectAsync(new Uri(c.BaseUrl.Replace("https://","wss://").Replace("http://","ws://")+"/v1/ws?token="+Uri.EscapeDataString(c.Token)),ct);_=Read();}async Task Read(){var b=new byte[65536];while(ws.State==WebSocketState.Open){var r=await ws.ReceiveAsync(new ArraySegment<byte>(b),stop.Token);if(r.MessageType==WebSocketMessageType.Close)break;var x=JObject.Parse(Encoding.UTF8.GetString(b,0,r.Count));Event?.Invoke((string)x["type"],x["data"]);}}public Task Send(string t,object d=null){var x=new JObject{{"type",t}};if(d!=null)x["data"]=JToken.FromObject(d);var b=Encoding.UTF8.GetBytes(x.ToString(Formatting.None));return ws.SendAsync(new ArraySegment<byte>(b),WebSocketMessageType.Text,true,stop.Token);}public Task CreateRoom(string n,int m=0,object meta=null)=>Send("room.create",new{name=n,max_players=m,meta});public Task JoinRoom(string id)=>Send("room.join",new{room_id=id});public Task LeaveRoom()=>Send("room.leave");public Task State(object x)=>Send("room.state",new{state=x});public Task Chat(string c,string x)=>Send("chat.send",new{channel=c,content=x});public void Dispose(){stop?.Cancel();ws?.Dispose();}}
}
